<template>
  <div class="app-index-page" data-test="app-index-page">
    <!-- Sticky Header -->
    <div class="sticky-header">
      <div class="header-row">
        <div class="search-container">
          <Icon icon="mdi:magnify" class="search-icon" />
          <input
            ref="searchInput"
            v-model="searchQuery"
            type="text"
            :placeholder="$t('search_all_pages')"
            class="search-input"
            data-test="app-index-search"
            @keydown.escape="searchQuery = ''"
          />
          <div v-if="searchQuery" class="search-clear" @click="searchQuery = ''">
            <Icon icon="mdi:close" class="size-4" />
          </div>
          <span v-if="searchQuery" class="result-count">
            {{ filteredEntries.length }} {{ filteredEntries.length === 1 ? 'result' : 'results' }}
          </span>
        </div>

        <div class="header-actions">
          <div class="filter-pills">
            <button
              class="filter-pill"
              :class="{ active: activeTypeFilter === null }"
              @click="activeTypeFilter = null"
            >
              All
              <span class="pill-count">{{ totalCount }}</span>
            </button>
            <button
              v-for="typeOption in typeFilters"
              :key="typeOption.type"
              class="filter-pill"
              :class="{ active: activeTypeFilter === typeOption.type }"
              @click="activeTypeFilter = activeTypeFilter === typeOption.type ? null : typeOption.type"
            >
              <Icon :icon="typeOption.icon" class="size-3.5" />
              {{ typeOption.label }}
              <span class="pill-count">{{ typeOption.count }}</span>
            </button>
          </div>

          <button
            class="mode-toggle-btn"
            :class="{ active: devMode }"
            @click="toggleDevMode"
            :title="devMode ? 'Switch to User mode' : 'Switch to Developer mode'"
          >
            <Icon :icon="devMode ? 'mdi:code-tags' : 'mdi:account-outline'" class="size-3.5" />
            {{ devMode ? 'Dev' : 'User' }}
          </button>

          <HelpLink name="sitemap_page" data-test="help-link-sitemap" />
        </div>
      </div>
    </div>

    <!-- Main Content -->
    <div class="index-content">
      <!-- Overview Grid (compact sitemap view) -->
      <div v-if="!searchQuery && !activeTypeFilter" class="overview-grid">
        <div
          v-for="group in groupedEntries"
          :key="'ov-' + group.category"
          class="overview-block"
        >
          <h3
            class="overview-category"
            :title="getCategoryShortName(group.category)"
            @click="scrollToCategory(group.category)"
          >
            <Icon :icon="getCategoryIcon(group.category)" class="size-3.5 overview-category-icon" />
            <span class="overview-category-text">{{ getCategoryShortName(group.category) }}</span>
          </h3>
          <ul class="overview-links">
            <li
              v-for="entry in group.entries.slice(0, 8)"
              :key="'ov-' + entry.id"
              class="overview-link"
              @click="scrollToEntry(entry)"
            >
              {{ entry.label }}
            </li>
            <li
              v-if="group.entries.length > 8"
              class="overview-more"
              @click="scrollToCategory(group.category)"
            >
              +{{ group.entries.length - 8 }} more
            </li>
          </ul>
        </div>
      </div>

      <q-separator v-if="!searchQuery && !activeTypeFilter" class="overview-divider" />

      <!-- Empty State -->
      <div v-if="searchQuery && filteredEntries.length === 0" class="empty-state">
        <Icon icon="mdi:file-search-outline" class="size-12 text-muted-foreground" />
        <p class="empty-title">No results for "{{ searchQuery }}"</p>
        <p class="empty-hint">Try different keywords or browse the categories below</p>
        <button class="clear-search-btn" @click="searchQuery = ''">Clear search</button>
      </div>

      <!-- Grouped Results -->
      <template v-if="!searchQuery || filteredEntries.length > 0">
        <section
          v-for="group in groupedEntries"
          :key="group.category"
          :id="slugify(group.category)"
          class="category-section"
        >
          <div class="category-header">
            <Icon :icon="getCategoryIcon(group.category)" class="size-5 text-primary category-icon" />
            <h2 class="category-title" :title="categoryLabel(group.category)">{{ categoryLabel(group.category) }}</h2>
            <span class="category-count">{{ group.entries.length }}</span>
          </div>

          <!-- Subcategory grouping for In-Page Features -->
          <template v-if="group.category === 'In-Page Features' && !searchQuery">
            <div
              v-for="subgroup in getSubcategoryGroups(group.entries)"
              :key="subgroup.subcategory"
              class="subcategory-group"
            >
              <h3 class="subcategory-title">{{ subgroup.subcategory }}</h3>
              <div class="entries-grid">
                <div
                  v-for="entry in subgroup.entries"
                  :key="entry.id"
                  class="index-entry"
                  @click="navigateToEntry(entry)"
                >
                  <div class="entry-icon-wrapper">
                    <Icon :icon="entry.icon || 'mdi:file-outline'" class="entry-icon" />
                  </div>
                  <div class="entry-content">
                    <div class="entry-label-row">
                      <span
                        class="entry-label"
                        v-html="highlightMatch(entry.label)"
                      />
                      <span class="entry-type-badge" :class="'badge-' + entry.type">
                        {{ entry.type }}
                      </span>
                    </div>
                    <p
                      class="entry-description"
                      v-html="highlightMatch(entry.description)"
                    />
                    <div v-if="entry.triggeredFrom" class="entry-trigger">
                      <Icon icon="mdi:cursor-default-click-outline" class="size-3" />
                      {{ entry.triggeredFrom }}
                    </div>
                    <div v-if="devMode && entry.path" class="entry-path">
                      {{ entry.path }}
                    </div>
                    <div v-if="devMode && entry.params && entry.params.length > 0" class="entry-params">
                      <span
                        v-for="param in entry.params"
                        :key="param.name"
                        class="param-tag"
                      >
                        :{{ param.name }}
                        <q-tooltip>{{ param.description }}</q-tooltip>
                      </span>
                    </div>
                  </div>
                  <Icon
                    v-if="entry.path"
                    icon="mdi:chevron-right"
                    class="entry-arrow"
                  />
                </div>
              </div>
            </div>
          </template>

          <!-- Standard entries for other categories -->
          <div v-else class="entries-grid">
            <template v-for="entry in group.entries" :key="entry.id">
              <div
                class="index-entry"
                :class="{
                  'is-dialog': entry.type !== 'page',
                  'is-expanded': expandedEntryId === entry.id,
                  'has-resolver': !!entry.paramResolver,
                }"
                @click="navigateToEntry(entry, $event)"
              >
                <div class="entry-icon-wrapper">
                  <Icon :icon="entry.icon || 'mdi:file-outline'" class="entry-icon" />
                </div>
                <div class="entry-content">
                  <div class="entry-label-row">
                    <span
                      class="entry-label"
                      v-html="highlightMatch(entry.label)"
                    />
                    <span
                      v-if="devMode && entry.paramResolver"
                      class="entry-type-badge badge-resolver"
                    >
                      select type
                    </span>
                    <span
                      v-else-if="entry.type !== 'page'"
                      class="entry-type-badge"
                      :class="'badge-' + entry.type"
                    >
                      {{ entry.type }}
                    </span>
                    <Icon
                      v-if="devMode && entry.requiresAdmin"
                      icon="mdi:shield-account-outline"
                      class="size-3.5 text-muted-foreground"
                      title="Admin only"
                    />
                  </div>
                  <p
                    class="entry-description"
                    v-html="highlightMatch(entry.description)"
                  />
                  <div v-if="entry.triggeredFrom" class="entry-trigger">
                    <Icon icon="mdi:cursor-default-click-outline" class="size-3" />
                    {{ entry.triggeredFrom }}
                  </div>
                  <div v-if="devMode && entry.path" class="entry-path">
                    {{ entry.path }}
                  </div>
                </div>
                <Icon
                  v-if="entry.paramResolver"
                  :icon="expandedEntryId === entry.id ? 'mdi:chevron-up' : 'mdi:chevron-down'"
                  class="entry-arrow entry-arrow-visible"
                />
                <Icon
                  v-else-if="entry.path && !entry.params"
                  icon="mdi:chevron-right"
                  class="entry-arrow"
                />
              </div>

              <!-- Inline Doc Type Selector -->
              <div
                v-if="expandedEntryId === entry.id && entry.paramResolver === 'doc_type'"
                class="doctype-selector"
              >
                <div class="doctype-search">
                  <Icon icon="mdi:magnify" class="size-3.5 text-muted-foreground" />
                  <input
                    v-model="docTypeFilter"
                    type="text"
                    placeholder="Filter document types..."
                    class="doctype-search-input"
                    @click.stop
                  />
                </div>
                <div class="doctype-list">
                  <div
                    v-for="dt in getFilteredDocTypes()"
                    :key="dt.value"
                    class="doctype-item"
                    @click.stop="navigateWithDocType(entry, dt.value)"
                  >
                    <Icon icon="mdi:file-document-outline" class="size-3.5 text-muted-foreground" />
                    <span class="doctype-label">{{ dt.label }}</span>
                    <span class="doctype-key">{{ dt.value }}</span>
                    <Icon icon="mdi:chevron-right" class="size-3.5 text-muted-foreground doctype-arrow" />
                  </div>
                  <div v-if="getFilteredDocTypes().length === 0" class="doctype-empty">
                    No document types found
                  </div>
                </div>
              </div>

              <!-- Inline Document ID Selector -->
              <div
                v-if="expandedEntryId === entry.id && (entry.paramResolver === 'doc_id' || entry.paramResolver === 'deep_link_doc')"
                class="doctype-selector"
              >
                <div class="doctype-search">
                  <Icon icon="mdi:magnify" class="size-3.5 text-muted-foreground" />
                  <input
                    v-model="docTypeFilter"
                    type="text"
                    placeholder="Paste document ID or search..."
                    class="doctype-search-input"
                    @click.stop
                    @keydown.enter.stop="docTypeFilter.trim() && navigateWithDocId(entry, docTypeFilter.trim())"
                  />
                </div>
                <!-- Paste ID action -->
                <div v-if="docTypeFilter.trim()" class="doctype-list">
                  <div
                    class="doctype-item"
                    @click.stop="navigateWithDocId(entry, docTypeFilter.trim())"
                  >
                    <Icon icon="mdi:arrow-right-circle-outline" class="size-3.5 text-primary" />
                    <span class="doctype-label">Open with ID: {{ docTypeFilter.trim() }}</span>
                    <Icon icon="mdi:chevron-right" class="size-3.5 text-muted-foreground doctype-arrow" style="opacity:1" />
                  </div>
                </div>
                <!-- Dashboard documents -->
                <div class="doctype-list">
                  <div class="doctype-section-label">Dashboard Documents</div>
                  <div
                    v-for="doc in getFilteredDashboardDocs(entry)"
                    :key="doc.id"
                    class="doctype-item"
                    @click.stop="navigateWithDocId(entry, doc.id)"
                  >
                    <Icon icon="mdi:file-outline" class="size-3.5 text-muted-foreground" />
                    <span class="doctype-label">{{ doc.filename || doc.id }}</span>
                    <span class="doctype-key">{{ doc.doc_type }} · {{ doc.id.substring(0, 8) }}...</span>
                    <Icon icon="mdi:chevron-right" class="size-3.5 text-muted-foreground doctype-arrow" />
                  </div>
                  <div v-if="getFilteredDashboardDocs(entry).length === 0" class="doctype-empty">
                    No documents loaded. Paste a document ID above.
                  </div>
                </div>
              </div>
            </template>
          </div>
        </section>
      </template>
    </div>

    <!-- Back to top -->
    <button
      v-if="showBackToTop"
      class="back-to-top"
      @click="scrollToTop"
    >
      <Icon icon="mdi:chevron-up" class="size-5" />
    </button>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useTranslate } from '@tolgee/vue';
import {
  localizeRegistry,
  translateCategory,
  getActiveCategories,
  CATEGORIES,
  type IndexEntry,
  type EntryType,
  ENTRY_TYPE_LABELS,
} from 'src/utils/route-registry';
import { search, type SearchResult } from 'src/utils/route-search';
import { useDropdownStore, useDashboardStore } from 'src/store/main';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { filterActiveEntries, isModuleRouteActive } from 'src/utils/module-access';

interface TypeFilter {
  type: EntryType;
  label: string;
  icon: string;
  count: number;
}

interface SubcategoryGroup {
  subcategory: string;
  entries: IndexEntry[];
}

interface CategoryGroup {
  category: string;
  entries: IndexEntry[];
}

export default defineComponent({
  name: 'AppIndex',

  setup() {
    const dropdown_store = useDropdownStore();
    const { doc_type_list } = storeToRefs(dropdown_store);
    const dashboard_store = useDashboardStore();
    const { display_data } = storeToRefs(dashboard_store);
    const authStore = useAuthTokenStore();
    const setting_store = useSettingStore();
    const { user_settings } = storeToRefs(setting_store);
    const { t } = useTranslate();

    return {
      doc_type_list,
      display_data,
      authStore,
      user_settings,
      t,
    };
  },

  data() {
    return {
      searchQuery: '',
      activeTypeFilter: null as EntryType | null,
      activeCategoryAnchor: '' as string,
      showBackToTop: false,
      searchDebounceTimer: null as ReturnType<typeof setTimeout> | null,
      debouncedSearchResults: [] as SearchResult[],
      expandedEntryId: null as string | null,
      docTypeFilter: '',
      devMode: false,
    };
  },

  computed: {
    isAdmin(): boolean {
      return this.authStore.isAdmin();
    },

    /** Hidden types — menus and panels are not actionable from the sitemap */
    hiddenTypes(): EntryType[] {
      return ['menu', 'panel'];
    },

    /** Registry with label/description in the active locale. Recomputes on language change. */
    localizedRegistry(): IndexEntry[] {
      return localizeRegistry((key, fallback) => this.t(key, fallback));
    },

    visibleEntries(): IndexEntry[] {
      let entries = this.localizedRegistry.filter((e: IndexEntry) => !this.hiddenTypes.includes(e.type));
      if (!this.devMode) {
        entries = entries.filter((e: IndexEntry) => !e.requiresAdmin || this.isAdmin);
      }
      return filterActiveEntries(entries, this.user_settings);
    },

    totalCount(): number {
      return this.visibleEntries.length;
    },

    activeCategories(): string[] {
      return getActiveCategories();
    },

    typeCounts(): Record<string, number> {
      const counts: Record<string, number> = {};
      for (const entry of this.visibleEntries) {
        counts[entry.type] = (counts[entry.type] || 0) + 1;
      }
      return counts as Record<EntryType, number>;
    },

    typeFilters(): TypeFilter[] {
      const iconMap: Record<EntryType, string> = {
        page: 'mdi:file-document-outline',
        dialog: 'mdi:message-text-outline',
        sidebar: 'mdi:page-layout-sidebar-right',
        panel: 'mdi:view-split-vertical',
        menu: 'mdi:menu',
        action: 'mdi:cursor-default-click-outline',
      };

      return Object.entries(this.typeCounts)
        .filter(([, count]) => (count as number) > 0)
        .map(([type, count]) => ({
          type: type as EntryType,
          label: ENTRY_TYPE_LABELS[type as EntryType] || type,
          icon: iconMap[type as EntryType] || 'mdi:circle-outline',
          count: count as number,
        }));
    },

    filteredEntries(): IndexEntry[] {
      let entries: IndexEntry[];

      if (this.searchQuery.trim()) {
        entries = this.debouncedSearchResults.map((r) => r.entry);
      } else {
        entries = [...this.visibleEntries];
      }

      if (this.activeTypeFilter) {
        entries = entries.filter((e) => e.type === this.activeTypeFilter);
      }

      return entries;
    },

    groupedEntries(): CategoryGroup[] {
      if (this.searchQuery.trim()) {
        // Group search results by category
        const groups = new Map<string, IndexEntry[]>();
        for (const entry of this.filteredEntries) {
          if (!groups.has(entry.category)) {
            groups.set(entry.category, []);
          }
          groups.get(entry.category)!.push(entry);
        }

        const result: CategoryGroup[] = [];
        for (const cat of this.activeCategories) {
          const catEntries = groups.get(cat);
          if (catEntries && catEntries.length > 0) {
            result.push({ category: cat, entries: catEntries });
          }
        }
        return result;
      }

      // No search — build groups from visible entries (respects user/dev mode filtering)
      const grouped = new Map<string, IndexEntry[]>();
      for (const category of CATEGORIES) {
        const catEntries = this.visibleEntries.filter((e: IndexEntry) => e.category === category);
        if (catEntries.length > 0) {
          grouped.set(category, catEntries);
        }
      }
      const result: CategoryGroup[] = [];
      for (const [category, entries] of grouped) {
        let filtered = entries;
        if (this.activeTypeFilter) {
          filtered = entries.filter((e) => e.type === this.activeTypeFilter);
        }
        if (filtered.length > 0) {
          result.push({ category, entries: filtered });
        }
      }
      return result;
    },
  },

  watch: {
    searchQuery(newVal: string) {
      // Sync to URL
      const url = new URL(window.location.href);
      if (newVal) {
        url.searchParams.set('q', newVal);
      } else {
        url.searchParams.delete('q');
      }
      window.history.replaceState({}, '', url.toString());

      // Debounced search
      if (this.searchDebounceTimer) {
        clearTimeout(this.searchDebounceTimer);
      }
      this.searchDebounceTimer = setTimeout(() => {
        this.performSearch(newVal);
      }, 150);
    },
  },

  mounted() {
    // Read dev mode from URL (takes precedence) or localStorage
    const urlDev = new URLSearchParams(window.location.search).get('dev');
    if (urlDev === '1') {
      this.devMode = true;
    } else {
      this.devMode = localStorage.getItem('sitemap-dev-mode') === 'true';
    }

    // Read query from URL
    const urlQuery = new URLSearchParams(window.location.search).get('q');
    if (urlQuery) {
      this.searchQuery = urlQuery;
      this.performSearch(urlQuery);
    }

    // Read type filter from URL
    const urlType = new URLSearchParams(window.location.search).get('type');
    if (urlType && ['page', 'dialog', 'sidebar', 'panel', 'menu', 'action'].includes(urlType)) {
      this.activeTypeFilter = urlType as EntryType;
    }

    // Scroll listener for back-to-top and category tracking
    window.addEventListener('scroll', this.handleScroll);

    // Cmd+K is handled globally by QuickSearchModal — no local override
  },

  unmounted() {
    window.removeEventListener('scroll', this.handleScroll);
    if (this.searchDebounceTimer) {
      clearTimeout(this.searchDebounceTimer);
    }
  },

  methods: {
    performSearch(query: string) {
      if (!query.trim()) {
        this.debouncedSearchResults = [];
        return;
      }
      this.debouncedSearchResults = search(query, { registry: this.localizedRegistry }).filter((result) =>
        isModuleRouteActive(result.entry.path, this.user_settings),
      );
    },

    navigateToEntry(entry: IndexEntry, event?: Event) {
      // deep_link: navigate directly to host page with ?open= query param
      if (entry.paramResolver === 'deep_link' && entry.deepLinkPath) {
        const query: Record<string, string> = {};
        let basePath = entry.deepLinkPath;
        if (basePath.includes('?')) {
          const [p, qs] = basePath.split('?');
          basePath = p;
          new URLSearchParams(qs).forEach((v, k) => { query[k] = v; });
        }
        if (entry.deepLinkAction) query.open = entry.deepLinkAction;
        this.$router.push({ path: basePath, query });
        return;
      }

      // Entries that need a picker (doc_type, doc_id, deep_link_doc)
      if (entry.paramResolver) {
        if (event) event.stopPropagation();
        this.expandedEntryId = this.expandedEntryId === entry.id ? null : entry.id;
        this.docTypeFilter = '';
        return;
      }

      if (entry.path) {
        this.pushEntryRoute(entry.path);
      }
    },

    /** Navigate to a path that may contain ?query params */
    pushEntryRoute(fullPath: string) {
      // Handle paths with query params like /workflowsdashboard?tab=workflowlist
      if (fullPath.includes('?')) {
        const [path, queryString] = fullPath.split('?');
        const query: Record<string, string> = {};
        new URLSearchParams(queryString).forEach((v, k) => { query[k] = v; });
        this.$router.push({ path, query });
        return;
      }
      // For routes with required params but no resolver, skip
      const hasRequiredParams = fullPath.includes('/:') &&
        !fullPath.includes('?');
      if (hasRequiredParams) {
        return;
      }
      // Strip optional params
      const navPath = fullPath.replace(/\/:[^/]+\?/g, '');
      this.$router.push(navPath);
    },

    /** Scroll to a specific entry in the detail section */
    scrollToEntry(entry: IndexEntry) {
      // First scroll to the category
      const slug = this.slugify(entry.category);
      const section = document.getElementById(slug);
      if (section) {
        section.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    },

    navigateWithDocId(entry: IndexEntry, docId: string) {
      if (entry.paramResolver === 'deep_link_doc') {
        // Navigate to host page with ?open=action&doc_id=id
        this.$router.push({
          path: entry.deepLinkPath || '/dashboard',
          query: { open: entry.deepLinkAction, doc_id: docId },
        });
      } else if (entry.path && entry.paramResolverTarget) {
        // doc_id resolver — replace :id in path
        let resolvedPath = entry.path;
        resolvedPath = resolvedPath.replace(`:${entry.paramResolverTarget}`, docId);
        resolvedPath = resolvedPath.replace(/\/:[^/]+\?/g, '');
        resolvedPath = resolvedPath.replace(/\/:[^/]+/g, '');
        this.$router.push(resolvedPath);
      }
      this.expandedEntryId = null;
    },

    getFilteredDashboardDocs(entry?: IndexEntry): any[] {
      let docs = this.display_data || [];
      // Apply status filter from entry
      if (entry?.statusFilter?.length) {
        docs = docs.filter((doc: any) => entry.statusFilter!.includes(doc.status));
      }
      if (!this.docTypeFilter) return docs.slice(0, 15);
      const q = this.docTypeFilter.toLowerCase();
      return docs.filter((doc: any) =>
        doc.filename?.toLowerCase().includes(q) ||
        doc.id?.toLowerCase().includes(q) ||
        doc.doc_type?.toLowerCase().includes(q),
      ).slice(0, 15);
    },

    navigateWithDocType(entry: IndexEntry, docTypeKey: string) {
      if (!entry.path || !entry.paramResolverTarget) return;

      let resolvedPath = entry.path;
      const target = entry.paramResolverTarget;

      // Replace the target param
      resolvedPath = resolvedPath.replace(`:${target}`, docTypeKey);

      // Strip remaining optional params
      resolvedPath = resolvedPath.replace(/\/:[^/]+\?/g, '');

      // For paths that still have required params (like :id), strip them
      // Some routes like /my_workflow/:doc_type/:id need both — just navigate to what we have
      resolvedPath = resolvedPath.replace(/\/:[^/]+/g, '');

      this.expandedEntryId = null;
      this.$router.push(resolvedPath);
    },

    getFilteredDocTypes(): any[] {
      const list = this.doc_type_list || [];
      if (!this.docTypeFilter) return list;
      const q = this.docTypeFilter.toLowerCase();
      return list.filter((dt: any) =>
        dt.label?.toLowerCase().includes(q) ||
        dt.value?.toLowerCase().includes(q)
      );
    },

    scrollToCategory(category: string) {
      const slug = this.slugify(category);
      const el = document.getElementById(slug);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        this.activeCategoryAnchor = category;
      }
    },

    scrollToTop() {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    },

    slugify(text: string): string {
      const slug = text
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)/g, '');
      return 'sitemap-' + slug;
    },

    /** Full translated category label (English string stays the grouping key). */
    categoryLabel(category: string): string {
      return translateCategory(category, (key, fallback) => this.t(key, fallback));
    },

    getCategoryShortName(category: string): string {
      const label = this.categoryLabel(category);
      const dash = label.indexOf('—');
      return dash >= 0 ? label.slice(dash + 1).trim() : label;
    },

    getCategoryIcon(category: string): string {
      const iconMap: Record<string, string> = {
        'Dashboard & Analytics': 'mdi:view-dashboard',
        'Document Processing': 'mdi:file-document-outline',
        'Workflows': 'mdi:sitemap-outline',
        'Suppliers': 'mdi:account-group',
        'Purchase Orders': 'mdi:file-document-check-outline',
        'Invoices': 'mdi:receipt-text-outline',
        'Shipping & ASN': 'mdi:truck-delivery-outline',
        'Reports & Statistics': 'mdi:chart-bar',
        'Search & Exploration': 'mdi:magnify',
        'DocNet': 'mdi:lan',
        'Settings — General': 'mdi:cog',
        'Settings — Document Config': 'mdi:file-cog-outline',
        'Settings — Integration': 'mdi:connection',
        'Settings — Advanced': 'mdi:tune',
        'Settings — Supplier Portal': 'mdi:account-cog-outline',
        'In-Page Features': 'mdi:puzzle-outline',
        'Support & Debug': 'mdi:lifebuoy',
        'Authentication': 'mdi:login',
      };
      return iconMap[category] || 'mdi:folder-outline';
    },

    getSubcategoryGroups(entries: IndexEntry[]): SubcategoryGroup[] {
      const groups = new Map<string, IndexEntry[]>();
      for (const entry of entries) {
        const sub = entry.subcategory || 'Other';
        if (!groups.has(sub)) {
          groups.set(sub, []);
        }
        groups.get(sub)!.push(entry);
      }
      return Array.from(groups.entries()).map(([subcategory, subEntries]) => ({
        subcategory,
        entries: subEntries,
      }));
    },

    highlightMatch(text: string): string {
      if (!this.searchQuery.trim()) return text;

      const query = this.searchQuery.trim();
      const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
      return text.replace(regex, '<mark class="search-highlight">$1</mark>');
    },

    handleScroll() {
      this.showBackToTop = window.scrollY > 400;

      // Track active category
      if (!this.searchQuery) {
        const sections = document.querySelectorAll('.category-section');
        for (const section of sections) {
          const rect = section.getBoundingClientRect();
          if (rect.top <= 200 && rect.bottom > 200) {
            const id = section.id;
            const cat = this.activeCategories.find(
              (c) => this.slugify(c) === id,
            );
            if (cat) {
              this.activeCategoryAnchor = cat;
            }
            break;
          }
        }
      }
    },

    toggleDevMode() {
      this.devMode = !this.devMode;
      localStorage.setItem('sitemap-dev-mode', String(this.devMode));
      const url = new URL(window.location.href);
      if (this.devMode) {
        url.searchParams.set('dev', '1');
      } else {
        url.searchParams.delete('dev');
      }
      window.history.replaceState({}, '', url.toString());
    },
  },
});
</script>

